1	package warranty
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件回归保障直接资格查询 Evaluate 与请求明细查询 RequestView 的职责区别：
10	// Evaluate 只按调用方给定的时刻返回资格依据与拒绝原因，即使该时刻已经晚于关联
11	// 承诺的到期时刻，也不确认承诺到期、不释放预留占用、不改变已用数量或写入取消
12	// 标记；RequestView 查看请求及其承诺明细时才会确认相关承诺到期。失败的直接
13	// 资格查询（空编号、未知请求）同样不借传入的较晚时刻改动任何承诺或库存。
14	
15	// evalScenarioStore 构造用户给出的主例：产品保修三十天、故障 NOISE 未被除外
16	// （除外清单含另一代码 FAULTX）；备件初始库存十件；购买后第十天预留六件并于
17	// 当天领取两件，承诺在购买后第二十天到期。
18	func evalScenarioStore(t *testing.T) (s *Store, deadline, commitExpiry time.Time) {
19		t.Helper()
20		purchase := t0
21		deadline = purchase.Add(30 * day)
22		commitExpiry = purchase.Add(20 * day)
23	
24		s = NewStore()
25		if err := s.RegisterProduct("p1", purchase, 30, []string{"FAULTX"}); err != nil {
26			t.Fatalf("register product: %v", err)
27		}
28		if err := s.RegisterPart("part1", 10); err != nil {
29			t.Fatalf("register part: %v", err)
30		}
31		if err := s.SubmitRequest("r1", "p1", "NOISE"); err != nil {
32			t.Fatalf("submit request: %v", err)
33		}
34		day10 := purchase.Add(10 * day)
35		if _, err := s.Reserve("c1", "r1", "part1", 6, commitExpiry, day10); err != nil {
36			t.Fatalf("reserve c1: %v", err)
37		}
38		if _, err := s.Use("u1", "c1", 2, day10); err != nil {
39			t.Fatalf("use u1: %v", err)
40		}
41		return s, deadline, commitExpiry
42	}
43	
44	// assertEvaluateExpiredBasis 断言过保时刻的资格依据：不合格、未命中除外，
45	// 拒绝原因只有 warranty_expired；购买时刻、保修天数与保修截止时刻仍是登记资料。
46	func assertEvaluateExpiredBasis(t *testing.T, e *Eligibility, deadline time.Time) {
47		t.Helper()
48		if e == nil {
49			t.Fatal("eligibility is nil")
50		}
51		if e.RequestID != "r1" || e.ProductID != "p1" || e.FaultCode != "NOISE" {
52			t.Fatalf("basis identity = %q/%q/%q, want r1/p1/NOISE", e.RequestID, e.ProductID, e.FaultCode)
53		}
54		if e.Eligible {
55			t.Fatalf("eligible = true, want false: %+v", e)
56		}
57		if e.Excluded {
58			t.Fatalf("excluded = true, want false: %+v", e)
59		}
60		if len(e.Reasons) != 1 || e.Reasons[0] != ReasonWarrantyExpired {
61			t.Fatalf("reasons = %v, want only [warranty_expired]", e.Reasons)
62		}
63		if !e.PurchaseTime.Equal(t0) {
64			t.Fatalf("purchase time = %v, want registered %v", e.PurchaseTime, t0)
65		}
66		if e.WarrantyDays != 30 {
67			t.Fatalf("warranty days = %d, want registered 30", e.WarrantyDays)
68		}
69		if !e.WarrantyExpiry.Equal(deadline) {
70			t.Fatalf("warranty expiry = %v, want %v", e.WarrantyExpiry, deadline)
71		}
72	}
73	
74	// assertC1Unconfirmed 断言仓库里的 c1 仍是尚未确认到期、未取消的原记录：
75	// 原数量六件、已用两件，归属与到期时刻不变。
76	func assertC1Unconfirmed(t *testing.T, s *Store, used int, commitExpiry time.Time) {
77		t.Helper()
78		c, err := s.Commitment("c1")
79		if err != nil {
80			t.Fatalf("commitment c1: %v", err)
81		}
82		if c.Quantity != 6 || c.Used != used {
83			t.Fatalf("c1 quantity/used = %d/%d, want 6/%d", c.Quantity, c.Used, used)
84		}
85		if c.Expired {
86			t.Fatalf("c1 confirmed expired by eligibility query: %+v", c)
87		}
88		if c.Canceled {
89			t.Fatalf("c1 canceled by eligibility query: %+v", c)
90		}
91		if c.RequestID != "r1" || c.PartID != "part1" || !c.Expiry.Equal(commitExpiry) {
92			t.Fatalf("c1 identity altered: %+v", c)
93		}
94	}
95	
96	// assertStock 断言备件账目三项数量：实物剩余 / 有效占用 / 可承诺。
97	func assertStock(t *testing.T, s *Store, now time.Time, physical, occupied, committable int) {
98		t.Helper()
99		st, err := s.PartStatus("part1", now)
100		if err != nil {
101			t.Fatalf("part status: %v", err)
102		}
103		if st.PhysicalRemaining != physical || st.ActiveOccupied != occupied || st.Committable != committable {
104			t.Fatalf("stock = phys %d / occupied %d / committable %d, want %d/%d/%d",
105				st.PhysicalRemaining, st.ActiveOccupied, st.Committable, physical, occupied, committable)
106		}
107	}
108	
109	// TestEvaluateAtLateTimeDoesNotConfirmCommitment 主例：承诺到期（第二十天）后
110	// 尚未通过其他操作确认到期时，直接在第三十一天查询资格，只返回该时刻的资格
111	// 依据与 warranty_expired 一项拒绝原因；查询之后取回承诺，原数量六件、已用
112	// 两件及尚未确认到期的记录保持原样，不能因这次查询写入取消或到期确认，库存
113	// 占用也不释放。
114	func TestEvaluateAtLateTimeDoesNotConfirmCommitment(t *testing.T) {
115		s, deadline, commitExpiry := evalScenarioStore(t)
116		day31 := t0.Add(31 * day)
117	
118		// 直接资格查询：第三十一天已过保（保修截止为第三十天），正常返回不合格，
119		// 拒绝原因只有 warranty_expired，依据仍是登记资料。
120		e, err := s.Evaluate("r1", day31)
121		if err != nil {
122			t.Fatalf("evaluate at day 31: %v", err)
123		}
124		assertEvaluateExpiredBasis(t, e, deadline)
125	
126		// 查询不确认承诺到期：第三十一天虽已超过承诺到期时刻（第二十天），c1 仍是
127		// 原数量六件、已用两件、未取消、未确认到期的记录。
128		assertC1Unconfirmed(t, s, 2, commitExpiry)
129	
130		// 资格查询曾使用较晚时刻不能替代本次时刻：回到保修期内的第十五天再查，
131		// 资格仍按第十五天判断为合格、无拒绝原因，登记依据不变。
132		day15 := t0.Add(15 * day)
133		e15, err := s.Evaluate("r1", day15)
134		if err != nil {
135			t.Fatalf("evaluate at day 15: %v", err)
136		}
137		if !e15.Eligible || e15.Excluded || len(e15.Reasons) != 0 {
138			t.Fatalf("day 15 eligibility = %+v, want eligible with no reasons", e15)
139		}
140		if !e15.PurchaseTime.Equal(t0) || e15.WarrantyDays != 30 || !e15.WarrantyExpiry.Equal(deadline) {
141			t.Fatalf("day 15 basis altered: %+v", e15)
142		}
143	
144		// 以第十五天继续操作：承诺尚未确认到期且本次时刻早于到期时刻，库存仍显示
145		// 实物剩余八件、有效占用四件、可承诺四件。
146		assertStock(t, s, day15, 8, 4, 4)
147	
148		// 用新的使用编号再领取一件仍能成功：承诺未用四件尚在，较早时刻不受早先
149		// 那次较晚时刻资格查询影响。
150		if _, err := s.Use("u2", "c1", 1, day15); err != nil {
151			t.Fatalf("use u2 at day 15: %v", err)
152		}
153		assertC1Unconfirmed(t, s, 3, commitExpiry)
154		// 账目变为实物七件、有效占用三件、可承诺四件。
155		assertStock(t, s, day15, 7, 3, 4)
156	}
157	
158	// TestRequestViewConfirmsExpiryAfterLateEvaluate 承接上一例的状态：直接资格
159	// 查询从不确认到期，而第三十一天查看该请求的明细时应确认原承诺到期——保留
160	// 六件原数量和三件已用数量，只释放剩余三件占用，实物七件不回补；一经确认，
161	// 之后即使查看较早时刻或用新编号在较早时刻领取，都不能重新开放这笔承诺。
162	func TestRequestViewConfirmsExpiryAfterLateEvaluate(t *testing.T) {
163		s, deadline, commitExpiry := evalScenarioStore(t)
164		day15 := t0.Add(15 * day)
165		day31 := t0.Add(31 * day)
166	
167		// 第三十一天直接查资格：不确认到期。
168		e, err := s.Evaluate("r1", day31)
169		if err != nil {
170			t.Fatalf("evaluate at day 31: %v", err)
171		}
172		assertEvaluateExpiredBasis(t, e, deadline)
173		assertC1Unconfirmed(t, s, 2, commitExpiry)
174	
175		// 第十五天再领取一件，证明承诺仍开放。
176		if _, err := s.Use("u2", "c1", 1, day15); err != nil {
177			t.Fatalf("use u2 at day 15: %v", err)
178		}
179		assertStock(t, s, day15, 7, 3, 4)
180	
181		// 第三十一天查看请求明细：这次查询确认原承诺到期。
182		v, err := s.RequestView("r1", day31)
183		if err != nil {
184			t.Fatalf("request view at day 31: %v", err)
185		}
186		if v.Eligibility == nil || v.Eligibility.Eligible ||
187			len(v.Eligibility.Reasons) != 1 || v.Eligibility.Reasons[0] != ReasonWarrantyExpired {
188			t.Fatalf("view eligibility = %+v, want only warranty_expired", v.Eligibility)
189		}
190		if len(v.Commitments) != 1 {
191			t.Fatalf("commitments = %+v, want exactly c1", v.Commitments)
192		}
193		d := v.Commitments[0]
194		// 保留六件原数量和三件已用数量，只释放剩余三件占用，状态 expired。
195		want := CommitmentDetail{
196			CommitmentID:      "c1",
197			RequestID:         "r1",
198			PartID:            "part1",
199			OriginalQuantity:  6,
200			UsedQuantity:      3,
201			RemainingQuantity: 3,
202			Expiry:            commitExpiry,
203			Status:            CommitmentExpired,
204		}
205		if d != want {
206			t.Fatalf("c1 detail = %+v, want %+v", d, want)
207		}
208	
209		// 仓库记录已被确认到期；只释放三件未用占用，已领走的三件实物不回补。
210		c, _ := s.Commitment("c1")
211		if !c.Expired || c.Canceled || c.Quantity != 6 || c.Used != 3 {
212			t.Fatalf("c1 after request view: %+v, want expired 6/3", c)
213		}
214		// 实物七件、有效占用为零、可承诺七件。
215		assertStock(t, s, day31, 7, 0, 7)
216	
217		// 之后即使查看较早时刻，也不能重新开放这笔已确认到期的承诺：
218		// 请求明细仍 expired，备件账目在较早时刻也不回退占用。
219		vEarly, err := s.RequestView("r1", day15)
220		if err != nil {
221			t.Fatalf("request view at day 15 after confirmation: %v", err)
222		}
223		if len(vEarly.Commitments) != 1 || vEarly.Commitments[0].Status != CommitmentExpired ||
224			vEarly.Commitments[0].OriginalQuantity != 6 || vEarly.Commitments[0].UsedQuantity != 3 ||
225			vEarly.Commitments[0].RemainingQuantity != 3 {
226			t.Fatalf("c1 reopened in early view: %+v", vEarly.Commitments)
227		}
228		assertStock(t, s, day15, 7, 0, 7)
229	
230		// 较早时刻用新使用编号领取：一律关闭，不扣库存、不改已用数量。
231		if _, err := s.Use("u3", "c1", 1, day15); !errors.Is(err, ErrCommitmentClosed) {
232			t.Fatalf("use after confirmed expiry at earlier time: got %v, want ErrCommitmentClosed", err)
233		}
234		assertStock(t, s, day15, 7, 0, 7)
235		c, _ = s.Commitment("c1")
236		if c.Used != 3 {
237			t.Fatalf("closed use changed c1 used: %+v", c)
238		}
239	}
240	
241	// TestEvaluateFailuresDoNotConfirmExpiry 承诺尚未确认到期时，失败的直接资格
242	// 查询也保持记录：空请求编号返回 ErrInvalidParam，未登记的请求编号返回
243	// ErrNotFound；即使传入晚于承诺到期的时刻，也不借失败查询确认任何承诺到期或
244	// 改变库存，承诺在到期前时刻仍可领取。
245	func TestEvaluateFailuresDoNotConfirmExpiry(t *testing.T) {
246		s, _, commitExpiry := evalScenarioStore(t)
247		day15 := t0.Add(15 * day)
248		day31 := t0.Add(31 * day)
249	
250		// 传入晚于承诺到期（第二十天）的时刻：提前失败的查询不确认任何承诺。
251		if _, err := s.Evaluate("", day31); !errors.Is(err, ErrInvalidParam) {
252			t.Fatalf("empty request id: got %v, want ErrInvalidParam", err)
253		}
254		if _, err := s.Evaluate("rMissing", day31); !errors.Is(err, ErrNotFound) {
255			t.Fatalf("unknown request: got %v, want ErrNotFound", err)
256		}
257	
258		// c1 未被确认：原数量六件、已用两件、未取消，仍在有效期内可领取。
259		assertC1Unconfirmed(t, s, 2, commitExpiry)
260		assertStock(t, s, day15, 8, 4, 4)
261		if _, err := s.Use("u2", "c1", 1, day15); err != nil {
262			t.Fatalf("c1 closed by failed eligibility queries: %v", err)
263		}
264		// 领取成功后账目为七件、三件、四件。
265		assertStock(t, s, day15, 7, 3, 4)
266		assertC1Unconfirmed(t, s, 3, commitExpiry)
267	
268		// 再次以晚时刻对未知请求失败查询，仍不改动已开放的承诺。
269		if _, err := s.Evaluate("rMissing", day31); !errors.Is(err, ErrNotFound) {
270			t.Fatalf("unknown request again: got %v, want ErrNotFound", err)
271		}
272		c, _ := s.Commitment("c1")
273		if c.Expired || c.Canceled || c.Used != 3 {
274			t.Fatalf("c1 changed by repeated failed query: %+v", c)
275		}
276		assertStock(t, s, day15, 7, 3, 4)
277	}
