	// 领取后：实物剩余九件（十二减三），有效占用四件（七减三），可承诺五件。
	ps, err := s.PartStatus("PART-A", day5)
	must(err)
	fmt.Println("stock      :", ps.PhysicalRemaining, ps.ActiveOccupied, ps.Committable)

	// 购买后第三十一天直接查询资格。注意：这是一次正常、成功的查询——
